item.command:
/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0;
  reg rst_n=0;
  reg a=0;
  wire match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));
  always #5 clk = ~clk;

  task shift_bit(input reg bitval);
    begin
      a = bitval;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b a_tem=%08b match=%0b", $time, a, dut.a_tem, match);
    end
  endtask

  initial begin
    $display("start");
    #1;
    @(negedge clk);
    rst_n = 0;
    @(negedge clk);
    rst_n = 1;
    // shift 01110001
    shift_bit(0);
    shift_bit(1);
    shift_bit(1);
    shift_bit(1);
    shift_bit(0);
    shift_bit(0);
    shift_bit(0);
    shift_bit(1);
    #10;
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv tb.sv TopModule.sv && vvp simv'

